const rightAnim=document.querySelectorAll(".right-anim"),observerRight=new IntersectionObserver(entries=>{entries.forEach(entry=>{entry.isIntersecting?entry.target.classList.add("right-anim-class"):entry.target.classList.remove("right-anim-class")})},{threshold:0});rightAnim.forEach(el=>observerRight.observe(el));const leftAnim=document.querySelectorAll(".left-anim"),observerLeft=new IntersectionObserver(entries=>{entries.forEach(entry=>{entry.isIntersecting?entry.target.classList.add("left-anim-class"):entry.target.classList.remove("left-anim-class")})},{threshold:0});leftAnim.forEach(el=>observerLeft.observe(el));const topAnim=document.querySelectorAll(".top-anim"),observertop=new IntersectionObserver(entries=>{entries.forEach(entry=>{entry.isIntersecting?entry.target.classList.add("top-anim-class"):entry.target.classList.remove("top-anim-class")})},{threshold:0});topAnim.forEach(el=>observertop.observe(el));const bottomAnim=document.querySelectorAll(".bottom-anim"),observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{entry.isIntersecting?entry.target.classList.add("bottom-anim-class"):entry.target.classList.remove("bottom-anim-class")})},{threshold:0});bottomAnim.forEach(el=>observer.observe(el));const blendInElements=document.querySelectorAll(".blend-in"),observerBlendIn=new IntersectionObserver(entries=>{entries.forEach(entry=>{entry.isIntersecting?entry.target.classList.add("blend-in-class"):entry.target.classList.remove("blend-in-class")})},{threshold:0});blendInElements.forEach(el=>observerBlendIn.observe(el));